// Current-board inspection and replay of actual recorded history only. No future search or move recommendations.
const g102Inspect = function(raw){ const s=raw.content.filter(x=>x.type==="text").map(x=>x.text).join("\n"); const cols="ABCDEFGHJ"; const b=Array(81).fill("."); for(const line of s.split("\n")){const m=line.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]\s*$/);if(m){m[2].trim().split(/\s+/).forEach((v,x)=>b[(Number(m[1])-1)*9+x]=v);}} const name=i=>cols[i%9]+(Math.floor(i/9)+1); const adj=i=>[i%9>0?i-1:-1,i%9<8?i+1:-1,i>=9?i-9:-1,i<72?i+9:-1].filter(x=>x>=0);const seen=new Set(),groups=[],regions=[];for(let i=0;i<81;i++){if(seen.has(i))continue;const color=b[i],q=[i],points=[],libs=new Set(),border=new Set();seen.add(i);while(q.length){const v=q.pop();points.push(v);for(const n of adj(v)){if(b[n]===color&&!seen.has(n)){seen.add(n);q.push(n);}else if(b[n]!==color){if(b[n]===".")libs.add(n);else border.add(b[n]);}}}const obj={color,points:points.map(name).sort(),liberties:[...libs].map(name).sort(),border:[...border].sort()};if(color===".")regions.push(obj);else groups.push(obj);}const area={B:b.filter(x=>x==="X").length,W:b.filter(x=>x==="O").length,neutral:0};for(const r of regions){if(r.border.length===1)area[r.border[0]==="X"?"B":"W"]+=r.points.length;else area.neutral+=r.points.length;}return {board:b,groups,regions,area};};
const verifyRecorded = function(log){const cols="ABCDEFGHJ"; const board=Array(81).fill(".");let ko=null;const captures={B:0,W:0},moves=[],events=[],checks=[];const adj=i=>[i%9?i-1:-1,i%9<8?i+1:-1,i>=9?i-9:-1,i<72?i+9:-1].filter(v=>v>=0);const coord=i=>cols[i%9]+(Math.floor(i/9)+1);const index=p=>cols.indexOf(p[0])+9*(Number(p.slice(1))-1);const group=i=>{const color=board[i],seen=new Set([i]),q=[i],libs=new Set();while(q.length){const v=q.pop();for(const n of adj(v)){if(board[n]===color&&!seen.has(n)){seen.add(n);q.push(n);}else if(board[n]===".")libs.add(n);}}return {points:[...seen],libs:[...libs]};};function play(color,move){const symbol=color==="B"?"X":"O",enemy=color==="B"?"O":"X";const n=moves.length+1;if(move==="pass"){ko=null;moves.push({n,color,move});return;}const i=index(move);if(i<0||i>=81||board[i]!=="."||i===ko)throw Error("illegal recorded move "+n+" "+move);board[i]=symbol;const taken=[];for(const j of adj(i)){if(board[j]===enemy){const g=group(j);if(!g.libs.length){taken.push(...g.points);g.points.forEach(v=>board[v]=".");}}}const own=group(i);if(!own.libs.length)throw Error("recorded suicide "+n);captures[color]+=taken.length;ko=taken.length===1&&own.points.length===1&&own.libs.length===1?taken[0]:null;moves.push({n,color,move});if(taken.length)events.push({n,color,move,captured:taken.map(coord)});}
for(const snap of log.snapshots){const s=snap.raw.content.filter(x=>x.type==="text").map(x=>x.text).join("\n");if(snap.kind==="selection"){const first=s.match(/It plays first: ([A-HJ][1-9])\./);if(!first)throw Error("missing opening");play("B",first[1]);}else if(snap.kind==="play"){play("W",snap.submitted);const opp=s.match(/Your opponent played ([A-HJ][1-9])\./);if(opp)play("B",opp[1]);else if(/Your opponent passed\./.test(s))play("B","pass");else throw Error("missing opponent move");}const expected=g102Inspect(snap.raw).board;const cap=s.match(/Captured by Black: (\d+); by White: (\d+)/);const next=s.match(/Move number: (\d+)/);const marker=s.match(/Ko point: ([^.]+)\./);const check={kind:snap.kind,through:moves.length,board:expected.every((v,i)=>v===board[i]),captures:Number(cap[1])===captures.B&&Number(cap[2])===captures.W,next:Number(next[1])===moves.length+1,ko:marker[1]===(ko===null?"none":coord(ko))};checks.push(check);if(!check.board||!check.captures||!check.next||!check.ko)throw Error("snapshot mismatch "+JSON.stringify(check));}
return {moves,captureEvents:events,snapshotChecks:checks,allMatched:true,final:g102Inspect(log.snapshots.at(-1).raw),captures};};
